"""Turn ``pip freeze`` output on standard input into a constraints file.

Called by scripts/lock.sh, which supplies the platform tag as the only argument.
Editable installs, the packaging toolchain, and anything installed from a local
path are dropped: none of them pins a version another machine can resolve.
"""

from __future__ import annotations

import sys

SKIP = {"pip", "setuptools", "wheel", "benchproofer"}

HEADER = """\
# Version lock for {tag}, generated by scripts/lock.sh. Do not edit by hand.
#
# Applied by scripts/setup.sh and by continuous integration, so that an install
# resolves to the dependency tree this project is tested against. Constraints are
# not requirements: nothing here is installed unless pyproject.toml asks for it,
# directly or through another package.
"""


def pins(lines: list[str]) -> list[str]:
    """The version pins worth recording, sorted case-insensitively."""
    kept = []
    for line in lines:
        entry = line.strip()
        if not entry or entry.startswith("#") or "==" not in entry or " @ " in entry:
            continue
        if entry.split("==", 1)[0].lower().replace("_", "-") in SKIP:
            continue
        kept.append(entry)
    return sorted(kept, key=str.lower)


def main() -> None:
    tag = sys.argv[1] if len(sys.argv) > 1 else "this platform"
    sys.stdout.write(HEADER.format(tag=tag))
    sys.stdout.write("".join(f"{pin}\n" for pin in pins(sys.stdin.readlines())))


if __name__ == "__main__":
    main()
